import type { Component, HTMLAttributes } from 'vue'

export type FileExplorerItemType = 'file' | 'folder'

/**
 * A node in the tree. Folders hold their children; files never need `children`.
 *
 * `TData` types the optional `data` field, so application metadata travels with
 * the node and comes back fully typed in slots and events.
 */
export interface FileExplorerItem<TData = unknown> {
  /** Stable, unique identifier. Selection, expansion and rendering keys all use it — never the name. */
  id: string
  name: string
  type: FileExplorerItemType
  /** A folder's contents. Omit it or pass `[]` for an empty folder. Ignored on files. */
  children?: FileExplorerItem<TData>[]
  /** Size in bytes. */
  size?: number
  modifiedAt?: Date | string
  /** Overrides the extension parsed from `name` when resolving the default icon. */
  extension?: string
  mimeType?: string
  disabled?: boolean
  /** Arbitrary application data. */
  data?: TData
}

/** Interaction state of a rendered item, passed to slots and the icon resolver. */
export interface FileExplorerItemState {
  /** Zero-based nesting depth. Root items are `0`. */
  depth: number
  expanded: boolean
  selected: boolean
  disabled: boolean
}

export type FileExplorerIconResolver<TData = unknown> = (
  item: FileExplorerItem<TData>,
  state: FileExplorerItemState,
) => Component | undefined

export type FileExplorerSize = 'sm' | 'md'

export interface FileExplorerSelectEvent<TData = unknown> {
  /** The item the user interacted with. */
  item: FileExplorerItem<TData>
  /** The full selection after the interaction. */
  selected: string[]
  originalEvent: Event
}

export interface FileExplorerMoveEvent<TData = unknown> {
  /** The dragged items. Items nested inside another dragged folder are left out. */
  items: FileExplorerItem<TData>[]
  /** The destination folder, or `null` for the root. */
  target: FileExplorerItem<TData> | null
}

export interface FileExplorerItemSlotProps<TData = unknown> extends FileExplorerItemState {
  item: FileExplorerItem<TData>
}

export interface FileExplorerLabelSlotProps<TData = unknown> extends FileExplorerItemSlotProps<TData> {
  /** The active search query, trimmed. Empty when not searching. */
  query: string
}

export interface FileExplorerNodeSlots<TData = unknown> {
  /** Replaces the icon and label of every item. The chevron, indentation and row stay in place. */
  item?: (props: FileExplorerItemSlotProps<TData>) => unknown
  icon?: (props: FileExplorerItemSlotProps<TData>) => unknown
  label?: (props: FileExplorerLabelSlotProps<TData>) => unknown
  /** Trailing content, pushed to the end of the row. */
  actions?: (props: FileExplorerItemSlotProps<TData>) => unknown
}

export interface FileExplorerSlots<TData = unknown> extends FileExplorerNodeSlots<TData> {
  /** Menu entries shown on right-click. `item` is `null` when the empty area was clicked. */
  'context-menu'?: (props: { item: FileExplorerItem<TData> | null }) => unknown
  empty?: (props: { query: string }) => unknown
  loading?: (props: Record<string, never>) => unknown
}

export interface FileExplorerProps<TData = unknown> {
  items?: FileExplorerItem<TData>[]
  /** Selected ids. Bind with `v-model:selected`. Always an array, even without `multiple`. */
  selected?: string[]
  /** Initial selection when `selected` is not bound. */
  defaultSelected?: string[]
  /** Expanded folder ids. Bind with `v-model:expanded`. */
  expanded?: string[]
  /** Initially expanded folder ids when `expanded` is not bound. */
  defaultExpanded?: string[]
  /** Filter query. Bind with `v-model:search`, or let `searchable` manage it. */
  search?: string
  /** Allows Ctrl/Cmd-click, Shift-click, Shift+Arrow and Ctrl/Cmd+A to select several items. */
  multiple?: boolean
  /** Renders a search field above the tree. */
  searchable?: boolean
  searchPlaceholder?: string
  /** Replaces the tree with skeleton rows (or the `loading` slot). */
  loading?: boolean
  disabled?: boolean
  /** Enables drag and drop. Listen to `move` to apply the change. */
  draggable?: boolean
  /** Picks the icon for an item. Return `undefined` to fall back to the default icon. */
  getIcon?: FileExplorerIconResolver<TData>
  size?: FileExplorerSize
  /** Draws indent guides next to nested items. */
  guides?: boolean
  /** Accessible name of the tree. */
  label?: string
  class?: HTMLAttributes['class']
}

export interface FileExplorerEmits<TData = unknown> {
  'update:selected': [value: string[]]
  'update:expanded': [value: string[]]
  'update:search': [value: string]
  /** The user selected an item with the pointer or keyboard. */
  select: [event: FileExplorerSelectEvent<TData>]
  /** A file was activated with Enter or a double-click. */
  open: [item: FileExplorerItem<TData>]
  /** Items were dropped on a folder (or the root). Only with `draggable`. */
  move: [event: FileExplorerMoveEvent<TData>]
}

import type { Component } from 'vue'
import {
  File,
  FileArchive,
  FileAudio,
  FileCode,
  FileCog,
  FileImage,
  FileJson,
  FileLock,
  FileSpreadsheet,
  FileTerminal,
  FileText,
  FileType,
  FileVideo,
  Folder,
  FolderOpen,
} from 'lucide-vue-next'
import type { FileExplorerItem, FileExplorerItemState } from './types'

export interface FileExplorerIndexEntry<TData = unknown> {
  item: FileExplorerItem<TData>
  parentId: string | null
  depth: number
}

export type FileExplorerIndex<TData = unknown> = Map<string, FileExplorerIndexEntry<TData>>

export function isFolder<TData>(item: FileExplorerItem<TData>): boolean {
  return item.type === 'folder'
}

/**
 * One pass over the tree that maps every id to its item, parent and depth.
 * Items are referenced, never copied.
 */
export function indexFileTree<TData>(items: FileExplorerItem<TData>[]): FileExplorerIndex<TData> {
  const index: FileExplorerIndex<TData> = new Map()
  const visit = (nodes: FileExplorerItem<TData>[], parentId: string | null, depth: number) => {
    for (const item of nodes) {
      index.set(item.id, { item, parentId, depth })
      if (item.children?.length) visit(item.children, item.id, depth + 1)
    }
  }
  visit(items, null, 0)
  return index
}

/** Whether `id` sits somewhere below `ancestorId`. */
export function isDescendantOf<TData>(index: FileExplorerIndex<TData>, id: string, ancestorId: string): boolean {
  let parentId = index.get(id)?.parentId ?? null
  while (parentId !== null) {
    if (parentId === ancestorId) return true
    parentId = index.get(parentId)?.parentId ?? null
  }
  return false
}

/** Ids of the items currently on screen, in the order they appear. */
export function getVisibleIds<TData>(items: FileExplorerItem<TData>[], expanded: ReadonlySet<string>): string[] {
  const ids: string[] = []
  const visit = (nodes: FileExplorerItem<TData>[]) => {
    for (const item of nodes) {
      ids.push(item.id)
      if (item.children && expanded.has(item.id)) visit(item.children)
    }
  }
  visit(items)
  return ids
}

export interface FileTreeFilterResult<TData = unknown> {
  items: FileExplorerItem<TData>[]
  /** Folders that must be open for every match to be visible. */
  revealIds: string[]
}

/**
 * Keeps the items whose name contains `query`, plus the folders leading to them.
 *
 * A folder whose own name matches is kept whole. A folder kept only for its
 * descendants is shallow-copied with a filtered `children` array; the input is
 * never mutated.
 */
export function filterFileTree<TData>(items: FileExplorerItem<TData>[], query: string): FileTreeFilterResult<TData> {
  const needle = query.trim().toLowerCase()
  if (!needle) return { items, revealIds: [] }

  const revealIds: string[] = []
  const visit = (nodes: FileExplorerItem<TData>[]): FileExplorerItem<TData>[] => {
    const kept: FileExplorerItem<TData>[] = []
    for (const item of nodes) {
      if (item.name.toLowerCase().includes(needle)) {
        kept.push(item)
        continue
      }
      if (!item.children?.length) continue
      const children = visit(item.children)
      if (children.length) {
        revealIds.push(item.id)
        kept.push({ ...item, children })
      }
    }
    return kept
  }

  return { items: visit(items), revealIds }
}

/** Splits `text` around case-insensitive occurrences of `query`, for highlighting. */
export function splitByQuery(text: string, query: string): { text: string, match: boolean }[] {
  const needle = query.trim().toLowerCase()
  if (!needle) return [{ text, match: false }]

  const parts: { text: string, match: boolean }[] = []
  const haystack = text.toLowerCase()
  let cursor = 0
  let found = haystack.indexOf(needle)
  while (found !== -1) {
    if (found > cursor) parts.push({ text: text.slice(cursor, found), match: false })
    parts.push({ text: text.slice(found, found + needle.length), match: true })
    cursor = found + needle.length
    found = haystack.indexOf(needle, cursor)
  }
  if (cursor < text.length) parts.push({ text: text.slice(cursor), match: false })
  return parts
}

const ICONS_BY_EXTENSION: Record<string, Component> = {}
const register = (icon: Component, extensions: string[]) => {
  for (const extension of extensions) ICONS_BY_EXTENSION[extension] = icon
}
register(FileCode, ['vue', 'ts', 'tsx', 'mts', 'cts', 'js', 'jsx', 'mjs', 'cjs', 'html', 'css', 'scss', 'sass', 'less', 'svelte', 'astro', 'py', 'go', 'rs', 'java', 'kt', 'swift', 'rb', 'php', 'c', 'h', 'cpp', 'cs', 'sql', 'graphql'])
register(FileJson, ['json', 'jsonc', 'json5'])
register(FileText, ['md', 'mdx', 'txt', 'rtf', 'pdf', 'doc', 'docx'])
register(FileImage, ['png', 'jpg', 'jpeg', 'gif', 'svg', 'webp', 'avif', 'ico', 'bmp'])
register(FileVideo, ['mp4', 'mov', 'webm', 'mkv', 'avi'])
register(FileAudio, ['mp3', 'wav', 'ogg', 'flac', 'm4a'])
register(FileArchive, ['zip', 'tar', 'gz', 'tgz', 'rar', '7z'])
register(FileSpreadsheet, ['csv', 'tsv', 'xls', 'xlsx'])
register(FileTerminal, ['sh', 'bash', 'zsh', 'fish', 'ps1'])
register(FileCog, ['yml', 'yaml', 'toml', 'ini', 'env', 'conf', 'config', 'editorconfig', 'gitignore'])
register(FileLock, ['lock'])
register(FileType, ['ttf', 'otf', 'woff', 'woff2'])

/** Lower-cased extension without the dot. `.env` resolves to `env`; `Makefile` to `''`. */
export function getFileExtension<TData>(item: FileExplorerItem<TData>): string {
  if (item.extension) return item.extension.replace(/^\./, '').toLowerCase()
  const dot = item.name.lastIndexOf('.')
  return dot === -1 ? '' : item.name.slice(dot + 1).toLowerCase()
}

/** The default icon resolver: open/closed folders, and a small set of generic file-type glyphs. */
export function getFileIcon<TData>(item: FileExplorerItem<TData>, state: Pick<FileExplorerItemState, 'expanded'>): Component {
  if (isFolder(item)) return state.expanded ? FolderOpen : Folder
  return ICONS_BY_EXTENSION[getFileExtension(item)] ?? File
}

import { cva, type VariantProps } from 'class-variance-authority'

/**
 * The row is a `group/row`, so slot content can react to it (`group-hover/row:…`).
 * A row's leading padding is `depth × --file-explorer-indent`. Override the
 * indent on the root, e.g. `class="[--file-explorer-indent:1.25rem]"`.
 */
export const fileExplorerRowVariants = cva(
  [
    'group/row flex w-full min-w-0 cursor-pointer select-none items-center gap-1.5 rounded-md pe-2 text-foreground/85',
    'ps-[calc(var(--file-explorer-depth)_*_var(--file-explorer-indent)_+_0.25rem)]',
    'transition-colors duration-100 motion-reduce:transition-none',
    'hover:bg-accent/70 hover:text-foreground',
    'data-[selected]:bg-accent data-[selected]:text-foreground',
    'data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50 data-[disabled]:hover:bg-transparent',
    'data-[dragging]:opacity-50',
    'data-[drop-target]:bg-primary/10 data-[drop-target]:ring-1 data-[drop-target]:ring-inset data-[drop-target]:ring-primary/40',
  ],
  {
    variants: {
      size: {
        sm: 'h-6 text-xs',
        md: 'h-7 text-sm',
      },
    },
    defaultVariants: {
      size: 'md',
    },
  },
)

export const fileExplorerIconVariants = cva('shrink-0 text-muted-foreground', {
  variants: {
    size: {
      sm: 'size-3.5',
      md: 'size-4',
    },
  },
  defaultVariants: {
    size: 'md',
  },
})

export type FileExplorerRowVariants = VariantProps<typeof fileExplorerRowVariants>

import { computed, type Ref } from 'vue'
import type { FileExplorerItem } from './types'
import { filterFileTree } from './utils'

/**
 * Client-side name filter. Derived purely from `items` and `query`, so there is
 * nothing to debounce: filtering is a single pass that only copies the folders
 * on a path to a match.
 */
export function useFileExplorerSearch<TData>(
  items: Readonly<Ref<FileExplorerItem<TData>[]>>,
  query: Readonly<Ref<string>>,
) {
  const normalizedQuery = computed(() => query.value.trim())
  const result = computed(() => filterFileTree(items.value, normalizedQuery.value))

  return {
    query: normalizedQuery,
    isSearching: computed(() => normalizedQuery.value.length > 0),
    items: computed(() => result.value.items),
    revealIds: computed(() => result.value.revealIds),
  }
}

import { ref, type Ref } from 'vue'

interface UseFileExplorerSelectionOptions {
  selected: Ref<string[]>
  multiple: Readonly<Ref<boolean>>
  /** Items on screen, in order. Ranges are computed over this list. */
  visibleIds: Readonly<Ref<string[]>>
  isSelectable: (id: string) => boolean
}

/**
 * Desktop-style selection over item ids: click replaces, Ctrl/Cmd toggles,
 * Shift extends a range from the last anchor.
 */
export function useFileExplorerSelection(options: UseFileExplorerSelectionOptions) {
  const { selected, multiple, visibleIds, isSelectable } = options
  const anchor = ref<string | null>(null)

  function replace(id: string) {
    selected.value = [id]
    anchor.value = id
  }

  function toggle(id: string) {
    if (!multiple.value) return replace(id)
    selected.value = selected.value.includes(id)
      ? selected.value.filter(value => value !== id)
      : [...selected.value, id]
    anchor.value = id
  }

  /** Selects everything between the anchor and `id`. The anchor stays put. */
  function extend(id: string) {
    const ids = visibleIds.value
    const from = anchor.value === null ? -1 : ids.indexOf(anchor.value)
    const to = ids.indexOf(id)
    if (!multiple.value || from === -1 || to === -1) return replace(id)

    const [start, end] = from < to ? [from, to] : [to, from]
    selected.value = ids.slice(start, end + 1).filter(isSelectable)
  }

  function selectAll() {
    if (!multiple.value) return
    selected.value = visibleIds.value.filter(isSelectable)
  }

  return { anchor, replace, toggle, extend, selectAll }
}

import { onBeforeUnmount, ref, shallowRef, type Ref } from 'vue'
import type { FileExplorerMoveEvent } from './types'
import { isDescendantOf, isFolder, type FileExplorerIndex } from './utils'

const AUTO_EXPAND_DELAY = 600

interface UseFileExplorerDragDropOptions<TData> {
  enabled: Readonly<Ref<boolean>>
  index: Readonly<Ref<FileExplorerIndex<TData>>>
  selected: Readonly<Ref<string[]>>
  isExpanded: (id: string) => boolean
  expand: (id: string) => void
  onMove: (event: FileExplorerMoveEvent<TData>) => void
}

/**
 * Native HTML5 drag and drop. The component only reports the intent through
 * `onMove`; moving the data is up to the consumer.
 *
 * Dragging a selected item drags the whole selection. Dropping on a file drops
 * into that file's folder. Drops into the item itself, into one of its own
 * descendants, or back into the folder it already lives in are refused.
 */
export function useFileExplorerDragDrop<TData>(options: UseFileExplorerDragDropOptions<TData>) {
  const { enabled, index, selected, isExpanded, expand, onMove } = options

  const draggingIds = shallowRef<readonly string[]>([])
  const dropTargetId = ref<string | null | undefined>(undefined)

  let expandTimer: ReturnType<typeof setTimeout> | undefined
  let expandCandidate: string | null = null

  function clearAutoExpand() {
    clearTimeout(expandTimer)
    expandTimer = undefined
    expandCandidate = null
  }

  function scheduleAutoExpand(folderId: string | null) {
    if (folderId === expandCandidate) return
    clearAutoExpand()
    if (folderId === null || isExpanded(folderId)) return
    expandCandidate = folderId
    expandTimer = setTimeout(() => expand(folderId), AUTO_EXPAND_DELAY)
  }

  function reset() {
    clearAutoExpand()
    draggingIds.value = []
    dropTargetId.value = undefined
  }

  function onDragStart(id: string, event: DragEvent) {
    if (!enabled.value) return
    const source = selected.value.includes(id) ? selected.value : [id]
    const ids = source.filter((candidate) => {
      const entry = index.value.get(candidate)
      if (!entry || entry.item.disabled) return false
      // Moving a folder already moves its contents.
      return !source.some(other => other !== candidate && isDescendantOf(index.value, candidate, other))
    })
    if (!ids.length) {
      event.preventDefault()
      return
    }

    draggingIds.value = ids
    if (event.dataTransfer) {
      event.dataTransfer.effectAllowed = 'move'
      // Some browsers refuse to start a drag without data.
      event.dataTransfer.setData('text/plain', ids.map(itemId => index.value.get(itemId)?.item.name ?? itemId).join('\n'))
    }
  }

  /** A folder receives the drop itself; a file forwards it to its parent. */
  function resolveTarget(id: string | null): string | null {
    if (id === null) return null
    const entry = index.value.get(id)
    if (!entry) return null
    return isFolder(entry.item) ? id : entry.parentId
  }

  function canDropInto(targetId: string | null): boolean {
    const ids = draggingIds.value
    if (!ids.length) return false
    if (targetId !== null && index.value.get(targetId)?.item.disabled) return false

    const intoItself = ids.some(id => id === targetId || (targetId !== null && isDescendantOf(index.value, targetId, id)))
    const alreadyThere = ids.every(id => index.value.get(id)?.parentId === targetId)
    return !intoItself && !alreadyThere
  }

  function onDragOver(id: string | null, event: DragEvent) {
    if (!draggingIds.value.length) return
    const targetId = resolveTarget(id)
    if (!canDropInto(targetId)) {
      dropTargetId.value = undefined
      clearAutoExpand()
      return
    }

    event.preventDefault()
    if (event.dataTransfer) event.dataTransfer.dropEffect = 'move'
    dropTargetId.value = targetId
    // Only hovering the folder row itself opens it, not hovering its files.
    scheduleAutoExpand(id !== null && id === targetId ? id : null)
  }

  function onDrop(event: DragEvent) {
    const targetId = dropTargetId.value
    if (targetId !== undefined && draggingIds.value.length) {
      event.preventDefault()
      const items = draggingIds.value.flatMap((id) => {
        const item = index.value.get(id)?.item
        return item ? [item] : []
      })
      const target = targetId === null ? null : index.value.get(targetId)?.item ?? null
      onMove({ items, target })
    }
    reset()
  }

  onBeforeUnmount(clearAutoExpand)

  return {
    draggingIds,
    dropTargetId,
    onDragStart,
    onDragOver,
    onDrop,
    onDragEnd: reset,
    /** Clears the highlight when the pointer leaves the explorer altogether. */
    onDragLeave(event: DragEvent) {
      const next = event.relatedTarget
      const container = event.currentTarget
      if (container instanceof Node && next instanceof Node && container.contains(next)) return
      dropTargetId.value = undefined
      clearAutoExpand()
    },
  }
}
